export type CopyKey = keyof typeof table;
export const copy: Readonly<Record<CopyKey, string>> = table;

export function t(key: CopyKey, params: Record<string, string> = {}): string {
  const text: string = copy[key];
  return text.replace(/\{([a-zA-Z_][a-zA-Z0-9_]*)\}/g, (m: string, p: string) => params[p] ?? m);
}
